Q: favicon.png vs favicon.ico - why should I use PNG instead of ICO? A: <p>We should now do the following:</p>
<pre><code>&lt;!-- Replaces the entire dozen-line snippet --&gt;
&lt;link rel=&quot;icon&quot; href=&quot;/favicon.ico&quot; sizes=&quot;32x32&quot;&gt;
&lt;link rel=&quot;icon&quot; href=&quot;/icon.svg&quot; type=&quot;image/svg+xml&quot;&gt;
&lt;link rel=&quot;apple-touch-icon&quot; href=&quot;/apple-touch-icon.png&quot;&gt;&lt;!-- 180×180 --&gt;

&lt;!-- Only if you're making a PWA --&gt;
&lt;link rel=&quot;manifest&quot; href=&quot;/manifest.webmanifest&quot;&gt;
</code></pre>
<p>If needed, manifest should look something like</p>
<pre><code>{
  &quot;icons&quot;: [
    { &quot;src&quot;: &quot;/icon-192.png&quot;, &quot;type&quot;: &quot;image/png&quot;, &quot;sizes&quot;: &quot;192x192&quot; },
    { &quot;src&quot;: &quot;/icon-mask.png&quot;, &quot;type&quot;: &quot;image/png&quot;, &quot;sizes&quot;: &quot;512x512&quot;, &quot;purpose&quot;: &quot;maskable&quot; },
    { &quot;src&quot;: &quot;/icon-512.png&quot;, &quot;type&quot;: &quot;image/png&quot;, &quot;sizes&quot;: &quot;512x512&quot; }
  ]
}
</code></pre>
<blockquote>
<p>Maskable icons should have <a href="https://w3c.github.io/manifest/#icon-masks" rel="nofollow noreferrer">bigger paddings</a>. The safe zone is a 409×409 circle. Use <a href="https://maskable.app" rel="nofollow noreferrer">maskable.app</a> to check your icon.
<sup>[<a href="https://evilmartians.com/chronicles/how-to-favicon-in-2021-six-files-that-fit-most-needs" rel="nofollow noreferrer">Source</a>]</sup></p>
</blockquote>

Q: Cannot read property &#39;collection&#39; of undefined while connecting to mongodb in node.js? A: <p>You should add this code <code>db = mongo.db('localhost:27017/yourdb');</code></p>

<pre><code>var mongo = require('mongoskin'),
    crypto = require('crypto');

module.exports = function (config) {

    var USERS_COLLECTION = 'users',
        ORDERS_COLLECTION = 'orders',
        salt = 'supersecretkey',
        db = mongo.db('localhost:27017/yourdb');

    authenticateUser: function (emailId, password, callback) {

        db.collection(USERS_COLLECTION).count({
            email: emailId,
            password: encryptPassword(password)
        }, function (err, count) {
            if (err) {
                console.log("error authenticating user: " + err);
                callback(new Error(err));
            } else if (count === 0) {
                callback(new Error("emailid/password did not match"));
            } else {
                callback(null);
            }
        });
    },
}
</code></pre>
